    #[test]
    fn test_plain_getter_can_call_application_value_function() {
        fn value(state: &State) -> i64 {
            state.names.len() as i64
        }
        wirefilter_fields! {
            impl HelperFields for State {
                "count" => {
                    fn(state: &State) -> i64 { value(state) }
                },
            }
        }
        let scheme = schema(&[("count", Type::Int, false)]);
        HelperFields::validate_scheme(&scheme).unwrap();
        let filter = scheme
            .parse("count == 1")
            .unwrap()
            .compile_with_compiler(&mut crate::DefaultCompiler::<(), HelperFields>::new());
        let state = State {
            scheme,
            names: vec![Box::from("accept")].into_boxed_slice(),
            country: None,
            lazy: OnceLock::new(),
        };
        assert!(filter.execute(&state).unwrap());
    }

    #[test]
    fn test_getters_with_field_metadata() {
        use crate::Field;

        fn check_field(state: &State, field: &Field, name: &str) {
            assert_eq!(field.as_ref(), state.scheme.get_field(name).unwrap());
        }

        wirefilter_fields! {
            impl MetadataFields for State {
                "names" => {
                    fn(state: &State, field: &Field) -> &[Box<str>] {
                        check_field(state, field, "names");
                        if state.names.is_empty() {
                            return &[];
                        }
                        &state.names
                    }
                },
                "count" => {
                    fn(state: &State, field: &crate::Field) -> i64 {
                        check_field(state, field, "count");
                        if state.names.is_empty() {
                            return 0;
                        }
                        state.names.len() as i64
                    }
                },
                "country" => {
                    fn(state: &State, field: &Field) -> Option<&str> {
                        check_field(state, field, "country");
                        state.country.as_deref()
                    }
                },
                "country_length" => {
                    fn(state: &State, field: &Field) -> Option<i64> {
                        check_field(state, field, "country_length");
                        Some(state.country.as_ref()?.len() as i64)
                    }
                },
            }
        }

        let scheme = schema(&[
            ("names", Type::array(Type::Bytes), false),
            ("count", Type::Int, false),
            ("country", Type::Bytes, true),
            ("country_length", Type::Int, true),
        ]);
        MetadataFields::validate_scheme(&scheme).unwrap();
        let mut compiler = crate::DefaultCompiler::<(), MetadataFields>::new();
        let filter = scheme
            .parse(r#"any(names[*] == "accept") and count == 1 and country == "GB" and country_length == 2"#)
            .unwrap()
            .compile_with_compiler(&mut compiler);
        let names_value = scheme
            .parse_value("names")
            .unwrap()
            .compile_with_compiler(&mut compiler);
        let country_value = scheme
            .parse_value("country")
            .unwrap()
            .compile_with_compiler(&mut compiler);
        let length_value = scheme
            .parse_value("country_length")
            .unwrap()
            .compile_with_compiler(&mut compiler);
        let mut state = State {
            scheme,
            names: vec![Box::from("accept")].into_boxed_slice(),
            country: Some("GB".into()),
            lazy: OnceLock::new(),
        };
        assert!(filter.execute(&state).unwrap());
        let crate::LhsValue::Array(names) = names_value.execute(&state).unwrap().unwrap() else {
            panic!("expected an array");
        };
        // The result borrows the context, not the field retained by the expression.
        drop(names_value);
        let crate::LhsValue::Bytes(bytes) = names.get(0).unwrap() else {
            panic!("expected bytes");
        };
        assert_eq!(bytes.as_ref().as_ptr(), state.names[0].as_ptr());
        assert_eq!(
            country_value.execute(&state).unwrap(),
            Ok(crate::LhsValue::from("GB"))
        );
        assert_eq!(
            length_value.execute(&state).unwrap(),
            Ok(crate::LhsValue::Int(2))
        );
        state.country = None;
        assert!(!filter.execute(&state).unwrap());
        assert_eq!(country_value.execute(&state).unwrap(), Err(Type::Bytes));
        assert_eq!(length_value.execute(&state).unwrap(), Err(Type::Int));
        state.names = Box::new([]);
        assert!(!filter.execute(&state).unwrap());
    }

    #[test]
    fn test_plain_returns_and_optional_values() {
        for optional_count in [false, true] {
            let mut defs = definitions();
            defs[3].2 = optional_count;
            let scheme = schema(&defs);
            Fields::validate_scheme(&scheme).unwrap();
            let mut compiler = crate::DefaultCompiler::<(), Fields>::new();
            let names = scheme
                .parse_value("names")
                .unwrap()
                .compile_with_compiler(&mut compiler);
            let count = scheme
                .parse_value("count")
                .unwrap()
                .compile_with_compiler(&mut compiler);
            let country = scheme
                .parse_value("country")
                .unwrap()
                .compile_with_compiler(&mut compiler);
            let mut state = State {
                scheme,
                names: Box::new([]),
                country: None,
                lazy: OnceLock::new(),
            };
            // Both plain bodies take an early-return branch for empty input.
            assert_eq!(count.execute(&state).unwrap(), Ok(crate::LhsValue::Int(0)));
            assert_eq!(country.execute(&state).unwrap(), Err(Type::Bytes));
            let crate::LhsValue::Array(empty) = names.execute(&state).unwrap().unwrap() else {
                panic!("expected a present empty array");
            };
            assert!(empty.is_empty());

            state.names = vec![Box::from("accept")].into_boxed_slice();
            state.country = Some("GB".into());
            assert_eq!(count.execute(&state).unwrap(), Ok(crate::LhsValue::Int(1)));
            assert_eq!(
                country.execute(&state).unwrap(),
                Ok(crate::LhsValue::from("GB"))
            );
            let crate::LhsValue::Array(values) = names.execute(&state).unwrap().unwrap() else {
                panic!("expected an array");
            };
            let crate::LhsValue::Bytes(bytes) = values.get(0).unwrap() else {
                panic!("expected bytes");
            };
            assert_eq!(bytes.as_ref().as_ptr(), state.names[0].as_ptr());
        }
    }

    #[test]
    fn test_mandatory_fields_reject_optional_getter_signatures() {
        wirefilter_fields! {
            impl OptionalFields for State {
                "borrowed" => {
                    fn(_state: &State) -> Option<&str> {
                        panic!("validation must not execute getters")
                    }
                },
                "owned" => {
                    fn(_state: &State, _field: &crate::Field) -> Option<i64> { Some(42) }
                },
                "explicit" => {
                    fn(_state: &State, _field: &crate::Field) -> Option<i64> provider crate::OwnedValueProvider<i64> {
                        None
                    }
                },
            }
        }
        let mut defs = [
            ("borrowed", Type::Bytes, false),
            ("owned", Type::Int, false),
            ("explicit", Type::Int, false),
        ];
        assert_eq!(
            OptionalFields::validate_scheme(&schema(&defs)),
            Err(SchemeValidationError(
                ["borrowed", "owned", "explicit"]
                    .map(|name| FieldDefinitionError::OptionalGetterForMandatoryField(name.into()))
                    .into(),
            ))
        );
        for (_, _, optional) in &mut defs {
            *optional = true;
        }
        assert_eq!(OptionalFields::validate_scheme(&schema(&defs)), Ok(()));
    }

    #[test]
    fn test_explicit_providers_support_plain_and_optional_returns() {
        wirefilter_fields! {
            impl<'data> ProviderFields for BorrowingState<'data> {
                "names" => {
                    provider crate::BorrowedValueProvider<[Box<str>]>;
                    fn(state: &BorrowingState<'data>, field: &crate::Field) -> &[Box<str>] {
                        assert_eq!(field.as_ref(), state.scheme.get_field("names").unwrap());
                        state.names
                    }
                },
                "first" => {
                    provider crate::BorrowedValueProvider<str>;
                    fn(state: &BorrowingState<'data>, field: &crate::Field) -> Option<&str> {
                        assert_eq!(field.as_ref(), state.scheme.get_field("first").unwrap());
                        Some(state.names.first()?.as_ref())
                    }
                },
                "legacy" => {
                    fn(state: &BorrowingState<'data>, field: &crate::Field) -> Option<&str>
                        provider crate::BorrowedValueProvider<str> {
                        assert_eq!(field.as_ref(), state.scheme.get_field("legacy").unwrap());
                        Some(state.names.first()?.as_ref())
                    }
                },
                "selection" => {
                    provider SelectionProvider;
                    fn(state: &BorrowingState<'data>, field: &crate::Field)
                        -> Option<crate::native::values::SliceView<'data, Box<str>>> {
                        assert_eq!(field.as_ref(), state.scheme.get_field("selection").unwrap());
                        state.names.first()?;
                        Some(crate::native::values::SliceView(state.names))
                    }
                },
            }
        }
        let scheme = schema(&[
            ("names", Type::array(Type::Bytes), false),
            ("first", Type::Bytes, true),
            ("legacy", Type::Bytes, true),
            ("selection", Type::array(Type::Bytes), true),
        ]);
        ProviderFields::validate_scheme(&scheme).unwrap();
        let mut compiler = crate::DefaultCompiler::<(), ProviderFields>::new();
        let names = [Box::<str>::from("accept")];
        for field in ["names", "first", "legacy", "selection"] {
            let value = scheme
                .parse_value(field)
                .unwrap()
                .compile_with_compiler(&mut compiler);
            let present = BorrowingState {
                scheme: &scheme,
                names: &names,
            };
            let result = value.execute(&present).unwrap().unwrap();
            let bytes = match &result {
                crate::LhsValue::Bytes(bytes) => bytes,
                crate::LhsValue::Array(values) => match values.get(0).unwrap() {
                    crate::LhsValue::Bytes(bytes) => bytes,
                    _ => panic!("expected bytes"),
                },
                _ => panic!("unexpected field type"),
            };
            assert_eq!(bytes.as_ref().as_ptr(), names[0].as_ptr());
            let absent = BorrowingState {
                scheme: &scheme,
                names: &[],
            };
            let result = value.execute(&absent).unwrap();
            if field == "names" {
                let crate::LhsValue::Array(values) = result.unwrap() else {
                    panic!("expected a present empty array");
                };
                assert!(values.is_empty());
            } else {
                assert_eq!(result, Err(scheme.get_field(field).unwrap().get_type()));
            }
        }
    }

    #[test]
    fn test_missing_unused_and_optional_fields() {
        for optional in [false, true] {
            let mut fields = definitions();
            fields.push(("unused", Type::Int, optional));
            assert_eq!(
                Fields::validate_scheme(&schema(&fields)),
                Err(SchemeValidationError(
                    vec![FieldDefinitionError::MissingGetter("unused".into())].into_boxed_slice()
                )),
            );
        }
    }

    #[test]
    fn test_unknown_getter() {
        let mut fields = definitions();
        fields.remove(1);
        assert_eq!(
            Fields::validate_scheme(&schema(&fields)),
            Err(SchemeValidationError(
                vec![FieldDefinitionError::UnknownField("country".into())].into_boxed_slice()
            )),
        );
    }

    #[test]
    fn test_nested_type_mismatch() {
        let mut fields = definitions();
        fields[0].1 = Type::array(Type::Int);
        assert_eq!(
            Fields::validate_scheme(&schema(&fields)),
            Err(SchemeValidationError(
                vec![FieldDefinitionError::TypeMismatch {
                    name: "names".into(),
                    scheme_type: Type::array(Type::Int),
                    getter_type: Type::array(Type::Bytes),
                }]
                .into_boxed_slice()
            )),
        );
    }

    #[test]
    fn test_all_registration_errors_reported_together() {
        let scheme = schema(&[("field", Type::Bytes, false), ("missing", Type::Int, true)]);
        assert_eq!(
            validate_field_definitions(
                &scheme,
                &[
                    ("field", Type::Int, false),
                    ("unknown", Type::Bool, false),
                    ("field", Type::Bytes, false),
                ]
            ),
            Err(SchemeValidationError(
                vec![
                    FieldDefinitionError::TypeMismatch {
                        name: "field".into(),
                        scheme_type: Type::Bytes,
                        getter_type: Type::Int,
                    },
                    FieldDefinitionError::UnknownField("unknown".into()),
                    FieldDefinitionError::DuplicateGetter("field".into()),
                    FieldDefinitionError::MissingGetter("missing".into()),
                ]
                .into_boxed_slice()
            )),
        );
    }
